sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float spacing;
uniform float width;
uniform float height;
uniform float tilt;
uniform float blink;
uniform float mode;
uniform float speed;
uniform float phase;
uniform float softness;
uniform float line;
layout(color) uniform half4 lid;

float pulse(float t) {
    float p = fract(t);
    float d = abs(p - 0.5) * 2.0;
    return pow(max(0.0, 1.0 - d * 2.5), 3.0);
}

half4 eye(half4 col, float2 coord, float2 c, float close) {
    float a = radians(tilt);
    float2 axis = float2(cos(a), sin(a));
    float2 normal = float2(-axis.y, axis.x);
    float2 q = coord - c;
    float u = dot(q, axis) / (width * size.x * 0.5 + 0.0001);
    float v = dot(q, normal) / (height * size.y * 0.5 + 0.0001);
    float d = length(float2(u, v));
    if (d >= 1.0) return col;
    float m = smoothstep(1.0, 1.0 - max(softness, 0.02), d);
    float side = v < 0.0 ? -1.0 : 1.0;
    half4 skin = image.eval(coord + normal * (side * close * height * size.y * 0.62));
    col = mix(col, skin, half(m * close));
    float crease = exp(-pow(v / 0.10, 2.0)) * m * close * line * lid.a;
    return half4(mix(col.rgb, lid.rgb, half(crease)), col.a);
}

half4 main(float2 coord) {
    float autoBlink = pulse(time * speed + phase);
    float close = clamp(mix(blink, autoBlink, step(0.5, mode)), 0.0, 1.0);
    half4 col = image.eval(coord);
    if (close <= 0.001) return col;
    float2 c = center * size;
    float a = radians(tilt);
    float2 axis = float2(cos(a), sin(a));
    float gap = spacing * size.x * 0.5;
    col = eye(col, coord, c - axis * gap, close);
    col = eye(col, coord, c + axis * gap, close);
    return col;
}
